const BLOCKED_COUNTRIES = ["KG"];
const ERROR_IMAGE = "data:image/jpeg;base64,";

function blockedPage() {
  return `<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#fff"><title>Сайт недоступен в вашем регионе</title><style>*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#fff}body{min-height:100vh;display:grid;place-items:center}img{display:block;width:min(100vw,177.78vh,1200px);height:auto;max-height:100vh;object-fit:contain}</style></head><body><img src="${ERROR_IMAGE}" alt="404 — страница не найдена"></body></html>`;
}

function requestCountry(context) {
  // Wrangler Pages Preview не всегда задаёт request.cf. Для локального предпросмотра
  // используем заголовок Cloudflare, который передаёт Quick Tunnel.
  const isLocalPagesPreview = context.env?.CF_PAGES === "1"
    && context.env?.CF_PAGES_BRANCH === "local";
  const value = isLocalPagesPreview
    ? context.request.headers.get("cf-ipcountry")
    : context.request.cf?.country;

  return typeof value === "string" ? value.trim().toUpperCase() : "";
}

export async function onRequest(context) {
  const country = requestCountry(context);

  if (BLOCKED_COUNTRIES.includes(country)) {
    return new Response(blockedPage(), {
      status: 403,
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store, max-age=0",
        "x-content-type-options": "nosniff",
        "x-robots-tag": "noindex"
      }
    });
  }

  return context.next();
}